for (std::size_t i = start; i < end && i < particleCount; ++i) {
    // Apply gravity (assuming y‑axis is vertical, positive upward)
    particles[i].vy -= g * deltaTime;

    // Integrate velocity → position (simple explicit Euler)
    particles[i].x += particles[i].vx * deltaTime;
    particles[i].y += particles[i].vy * deltaTime;
    particles[i].z += particles[i].vz * deltaTime;

    // Boundary handling – reflect with elasticity coefficient
    if (particles[i].x < -boxWidth) {
        particles[i].x = -boxWidth;
        particles[i].vx = -elasticity * particles[i].vx;
    } else if (particles[i].x > boxWidth) {
        particles[i].x = boxWidth;
        particles[i].vx = -elasticity * particles[i].vx;
    }

    if (particles[i].y < -boxWidth) {
        particles[i].y = -boxWidth;
        particles[i].vy = -elasticity * particles[i].vy;
    } else if (particles[i].y > boxWidth) {
        particles[i].y = boxWidth;
        particles[i].vy = -elasticity * particles[i].vy;
    }

    if (particles[i].z < -boxWidth) {
        particles[i].z = -boxWidth;
        particles[i].vz = -elasticity * particles[i].vz;
    } else if (particles[i].z > boxWidth) {
        particles[i].z = boxWidth;
        particles[i].vz = -elasticity * particles[i].vz;
    }
}

